{
  "enabled": true,
  "host": "127.0.0.1",
  "port": 9343,
  "openBrowserOnStart": false,
  "requireLocalToken": true,
  "database": {
    "filename": ""
  },
  "historyRetention": {
    "maxEntries": 1000,
    "maxBodyBytes": 65536,
    "persistBodies": true
  },
  "telemetry": {
    "enabled": true,
    "collectionIntervalMs": 15000,
    "retentionDays": 30,
    "pruneIntervalMinutes": 60,
    "persistRawSnapshot": true,
    "gpu": {
      "enabled": true,
      "nvidiaDcgmExporterUrl": null,
      "commandTimeoutMs": 5000
    }
  }
}

{
  "Rest": {
    "Hostname": "0.0.0.0",
    "Port": 9000,
    "Ssl": false,
    "RequireAuthentication": false
  },
  "Cors": {
    "Enabled": true,
    "AllowedOrigins": [
      "http://localhost:9100"
    ],
    "AllowedHeaders": [
      "Authorization",
      "Content-Type",
      "x-tenant-guid"
    ],
    "AllowedMethods": [
      "GET",
      "POST",
      "PUT",
      "DELETE",
      "OPTIONS"
    ]
  },
  "WebSocket": {
    "Enabled": true,
    "Path": "/ws/v1/clients",
    "HeartbeatIntervalMs": 15000,
    "RequestTimeoutMs": 120000
  },
  "Routing": {
    "DefaultTimeoutMs": 300000,
    "LoadBalancingMode": "RoundRobin",
    "Adaptive": {
      "SampleCount": 2,
      "CapacityWeight": 45,
      "InFlightWeight": 30,
      "ClientWeight": 15,
      "HeartbeatWeight": 10
    }
  },
  "Database": {
    "Type": "Sqlite",
    "Filename": "data/xeno.db"
  },
  "Logging": {
    "ConsoleLogging": true,
    "FileLogging": true,
    "LogDirectory": "logs",
    "LogFilename": "xeno.log"
  }
}
